//! The ported `@solidjs/universal` renderer (slice1/universal.rs, flatten.rs,
//! flow.rs) and Solid 2's event delegation (slice1/events.rs) against
//! Solid's own logs: each hand-written program of
//! docs/render-fuzz/tools/unit-programs.json runs on the render driver, and
//! its host log (every host call with arguments and results, handler calls,
//! the tree after each op) must equal the log fuzz/universal.mjs records on
//! Solid 2 rc.21 (fixtures/render-units.json, regenerated by
//! docs/render-fuzz/tools/unit-expectations.mjs).
use rust_solid::renderer::TreeRenderer;
use rust_solid::slice1::{InsertOptions, JsObj, Marker, Runtime, Universal, Value};
use serde_json::{json, Value as J};
use std::{
    cell::RefCell,
    io::Write,
    process::{Command, Stdio},
    rc::Rc,
};

fn driver(ops: &J) -> J {
    let mut child = Command::new(env!("CARGO_BIN_EXE_render-driver"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    writeln!(child.stdin.take().unwrap(), "{ops}").unwrap();
    let out = child.wait_with_output().unwrap();
    serde_json::from_slice(&out.stdout).unwrap()
}

fn unit(name: &str) {
    let all: J = serde_json::from_str(include_str!("fixtures/render-units.json")).unwrap();
    let case = &all[name];
    assert!(case.is_object(), "{name} is a unit program");
    let actual = driver(&case["ops"]);
    let (a, e) = (
        actual.as_array().unwrap(),
        case["expected"].as_array().unwrap(),
    );
    if let Some(i) = (0..a.len().max(e.len())).find(|i| a.get(*i) != e.get(*i)) {
        panic!(
            "{name}: first difference at entry {i}: expected {:?}, actual {:?}",
            e.get(i),
            a.get(i)
        );
    }
}

