/// The API a plan evaluator uses, without the driver: a render effect text
/// insert, a static insert and `TreeRenderer::frame`.
#[test]
fn api_insert_text_and_frame() {
    let mut rt = Runtime::default();
    let host = Rc::new(RefCell::new(TreeRenderer::new()));
    let u = Universal::new(host.clone());
    let s = rt.signal_value(Value::str("a"));
    let root = host.borrow().root();
    let el = u.create_element("p");
    u.append(root, el, None);
    let label = u.create_text(&Value::str("Filter: "));
    u.append(el, label, None);
    let acc = rt.accessor(s);
    u.insert(
        &mut rt,
        el,
        acc,
        Marker::Null,
        None,
        InsertOptions::default(),
    )
    .unwrap();
    u.insert(
        &mut rt,
        el,
        Value::Int(2),
        Marker::Null,
        None,
        InsertOptions::default(),
    )
    .unwrap();
    assert_eq!(host.borrow().frame(root), "Filter: a2");
    rt.write_value(s, Value::str("open"));
    assert_eq!(host.borrow().frame(root), "Filter: a2", "held until flush");
    rt.flush();
    assert_eq!(host.borrow().frame(root), "Filter: open2");
    assert_eq!(
        host.borrow().tree(root),
        json!([
            0,
            "#root",
            [[1, "p", [[2, "Filter: "], [6, "open"], [5, 2]]]]
        ])
    );
}

/// A row handler with an argument, as a plan's `call claim(issue.id)`:
/// `onClick={[claim, id]}` stores the handler and its data on the node
/// (delegated), and a click on the row's text calls `claim(id, event)`.
#[test]
fn api_delegated_handler_with_an_argument() {
    let mut rt = Runtime::default();
    let host = Rc::new(RefCell::new(TreeRenderer::new()));
    host.borrow_mut().register_delegated_root(0);
    let u = Universal::new(host.clone());
    let claimed = Rc::new(RefCell::new(vec![]));
    let seen = claimed.clone();
    let claim = rt.function(
        2,
        Rc::new(move |_rt: &mut Runtime, args: &[Value]| {
            seen.borrow_mut().push(args[0].clone());
            Ok(Value::Undef)
        }),
    );
    for id in [1, 3] {
        let b = u.create_element("button");
        let t = u.create_text(&Value::str("take"));
        u.append(b, t, None);
        u.append(0, b, None);
        let tuple = Value::Obj(JsObj::new_array(vec![claim.clone(), Value::Int(id)]));
        u.set_prop(b, "onClick", &tuple, &Value::Undef);
    }
    let targets = host.borrow().handlers_of(0, "click");
    assert_eq!(targets.len(), 2);
    let text = host.borrow().children(targets[1])[0];
    TreeRenderer::dispatch(&mut rt, &host, text, "click").unwrap();
    assert_eq!(*claimed.borrow(), vec![Value::Int(3)]);
}
